class Solution {
 bool path(TreeNode* node,int target,string& s){
  if(!node)return false;if(node->val==target)return true;
  s.push_back('L');if(path(node->left,target,s))return true;s.back()='R';
  if(path(node->right,target,s))return true;s.pop_back();return false;
 }
public:
 string getDirections(TreeNode* root,int startValue,int destValue){
  string a,b;path(root,startValue,a);path(root,destValue,b);
  int i=0;while(i<(int)min(a.size(),b.size()) && a[i]==b[i])++i;
  return string(a.size()-i,'U')+b.substr(i);
 }
};
